    "cat.k1.mk.r6f":"tərəfdaşla",
    "cat.k1.mk.r7n":"Dəri və klassik ayaqqabı, kiçik partiya",
    "cat.k1.mk.r7p":"Vençjou (温州), Çzeczyan əyaləti",
